'use strict';
(async()=>{
 const slides=await fetch('assets/photos.json').then(r=>r.json());
 const images=[document.querySelector('#photo-a'),document.querySelector('#photo-b')],caption=document.querySelector('.caption'),bar=document.querySelector('.progress i'),pauseButton=document.querySelector('#pause');
 let index=0,front=0,paused=matchMedia('(prefers-reduced-motion:reduce)').matches,overlay=null,timer,progressAnimation,moveAnimation,sequence=0,lastFocus,transitioning=false;
 const duration=8500,reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
 document.querySelector('#total').textContent=String(slides.filter(s=>!s.intro).length).padStart(2,'0');
 function preload(n){const img=new Image();img.src=slides[(n+slides.length)%slides.length].image;}
 function animatePhoto(){moveAnimation?.cancel();if(!reduced&&!slides[index].intro)moveAnimation=images[front].animate([{transform:'scale(1.065)'},{transform:'scale(1.005)'}],{duration:duration+1800,fill:'forwards',easing:'linear'});}
 function schedule(){clearTimeout(timer);progressAnimation?.cancel();progressAnimation=bar.animate([{transform:'scaleX(0)'},{transform:'scaleX(1)'}],{duration,fill:'forwards',easing:'linear'});if(paused||overlay||document.hidden){progressAnimation.pause();return;}timer=setTimeout(()=>go(index+1),duration);}
 function updatePause(){pauseButton.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow');pauseButton.innerHTML=paused?'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m7 4 8 6-8 6Z"/></svg>':'<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M7 5v10M13 5v10"/></svg>';}
 async function go(n){n=(n+slides.length)%slides.length;if(n===index)return;const seq=++sequence;clearTimeout(timer);const back=1-front;transitioning=true;images[back].src=slides[n].image;try{await images[back].decode();}catch{transitioning=false;schedule();return;}if(seq!==sequence)return;caption.classList.add('changing');await new Promise(r=>setTimeout(r,reduced?0:240));if(seq!==sequence)return;images[front].classList.remove('active');front=back;images[front].classList.add('active');index=n;document.body.classList.toggle('is-sunset',!!slides[index].intro);document.querySelector('#photo-title').textContent=slides[index].title;document.querySelector('#photo-category').textContent=slides[index].category;document.querySelector('#photo-description').textContent=slides[index].alt;document.querySelector('#current').textContent=String(index).padStart(2,'0');caption.classList.remove('changing');animatePhoto();schedule();preload(index+1);transitioning=false;}
 document.querySelector('.brand').onclick=e=>{e.preventDefault();go(1);};
 document.querySelector('.next').onclick=()=>go(index+1);document.querySelector('.previous').onclick=()=>go(index-1);
 pauseButton.onclick=()=>{paused=!paused;updatePause();if(paused){clearTimeout(timer);progressAnimation?.pause();moveAnimation?.pause();}else{moveAnimation?.play();schedule();}};
 function closeOverlay(){if(!overlay)return;overlay.hidden=true;overlay=null;document.body.style.overflow='';document.querySelector('.menu-button').setAttribute('aria-expanded','false');lastFocus?.focus();schedule();}
 function openOverlay(id){if(overlay)overlay.hidden=true;else lastFocus=document.activeElement;overlay=document.getElementById(id+'-panel');overlay.hidden=false;document.body.style.overflow='hidden';clearTimeout(timer);progressAnimation?.pause();document.querySelector('.menu-button').setAttribute('aria-expanded',id==='menu'?'true':'false');overlay.querySelector('button')?.focus();}
 document.querySelector('.menu-button').onclick=()=>openOverlay('menu');document.querySelector('#index-button').onclick=()=>openOverlay('index');document.querySelectorAll('.close-overlay').forEach(b=>b.onclick=closeOverlay);
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(b.dataset.go==='work'||b.dataset.go==='about'){closeOverlay();document.getElementById(b.dataset.go==='work'?'portfolio':'about').scrollIntoView({behavior:reduced?'instant':'smooth'});}else openOverlay(b.dataset.go);});
 const grid=document.querySelector('#photo-grid');slides.forEach((slide,n)=>{if(slide.intro)return;const button=document.createElement('button');button.setAttribute('aria-label','View '+slide.title);const frame=document.createElement('div');frame.className='thumbnail';const img=document.createElement('img');img.src=slide.thumb;img.alt=slide.alt;img.loading='lazy';frame.append(img);const number=document.createElement('small');number.textContent=String(n).padStart(2,'0');const title=document.createElement('strong');title.textContent=slide.title;button.append(frame,number,title);button.onclick=()=>{closeOverlay();go(n);};grid.append(button);});
 document.addEventListener('keydown',e=>{if(overlay){if(e.key==='Escape'){closeOverlay();return;}if(e.key==='Tab'){const nodes=[...overlay.querySelectorAll('button,a')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(e.key==='ArrowRight'){e.preventDefault();go(index+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(index-1);}if(e.code==='Space'&&document.activeElement===document.body){e.preventDefault();pauseButton.click();}});
 let touchX;document.querySelector('#portfolio').addEventListener('touchstart',e=>touchX=e.changedTouches[0].screenX,{passive:true});document.querySelector('#portfolio').addEventListener('touchend',e=>{const delta=e.changedTouches[0].screenX-touchX;if(Math.abs(delta)>60&&!overlay)go(index+(delta<0?1:-1));},{passive:true});
 if('IntersectionObserver' in window)new IntersectionObserver(entries=>{const inView=entries[0].isIntersecting;document.body.classList.toggle('on-about',!inView);if(!inView){clearTimeout(timer);progressAnimation?.pause();moveAnimation?.pause();}else if(!paused&&!overlay){moveAnimation?.play();schedule();}},{threshold:.35}).observe(document.querySelector('#portfolio'));
 document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(timer);progressAnimation?.pause();moveAnimation?.pause();}else{if(!paused)moveAnimation?.play();schedule();}});
 updatePause();animatePhoto();schedule();preload(1);
})();
